{"cards": [{"node_code": "N_a63587dc79133bc9", "definition": "研究铁路道床（有砟与无砟）的结构形式、材料特性、几何尺寸、铺设标准及与轨枕、路基相互作用关系的工程技术体系。", "boundary": "本节点聚焦于道床本体构造。边界在于区分“道床”与“轨枕”（轨枕归入轨枕节点）、“道床”与“路基”（路基归入路基节点）、“道床”与“线路理论”（道床力学计算归入理论）。若涉及道床材料性能，侧重材料本身归入线路工程材料，侧重道床结构归本节点。", "includes": ["有砟道床（碎石、级配、厚度）与无砟道床（混凝土板、沥青混凝土）构造", "道床断面尺寸、边坡、顶宽等几何参数及铺设工艺要求", "道床与轨枕、路基面的连接构造及排水设施"], "excludes": ["轨枕本体结构与材料（归入轨枕）", "路基填筑与防护工程（归入路基）", "道床动力响应与疲劳寿命理论分析（归入线路理论）"], "sibling_distinctions": [{"other_code": "N_bd517f04b88754bc", "rule": "区分依据为结构层级：道床是轨枕下方的支撑层，轨枕是连接钢轨与道床的构件；道床关注整体支撑结构，轨枕关注单个构件。"}, {"other_code": "N_2549075dd5698bc1", "rule": "区分依据为位置与功能：道床位于轨枕之下，起分散荷载和排水作用；路基位于道床之下，是线路的基础支撑体。"}], "cross_boundary_rule": "若内容涉及“道床-轨枕-路基”系统，若侧重道床结构形式与材料铺设，主挂载本节点；若侧重轨枕结构，主挂载轨枕；若侧重路基处理，主挂载路基。"}, {"node_code": "N_1c082c6a499152aa", "definition": "研究铁路线路与道路交叉处的道口构造、安全防护设施，以及线路沿线其他附属设备（如防护栅栏、排水沟、信号标志基础等）的结构与布置。", "boundary": "本节点聚焦于线路“附属”设施与“道口”构造。边界在于区分“道口”与“通信信号”（信号设备归入通信信号，道口栏杆机械结构归本节点）、“附属设备”与“线路主体”（路基、轨道归入各自节点）。若涉及道口信号控制逻辑，归入通信信号；若涉及道口路面结构，归本节点。", "includes": ["铁路道口（平交道口）的路面构造、警示标志、栏杆及防护设施", "线路防护栅栏、隔离网、排水沟、侧沟等附属设施构造", "线路标志、公里标、半公里标等附属设备的安装与结构"], "excludes": ["道口信号机、自动报警系统的电气控制逻辑（归入铁路通信、信号）", "路基、轨道、道岔等线路主体构造（归入各自节点）", "铁路房屋建筑（归入铁路房屋工程，若树中有独立节点）"], "sibling_distinctions": [{"other_code": "N_ea528fc63b654a25", "rule": "区分依据为功能：道岔是线路内部列车转向设备；道口是线路与外部道路交叉处的安全设施。"}, {"other_code": "N_2549075dd5698bc1", "rule": "区分依据为对象：路基是线路基础；道口及附属设备是线路沿线的安全与辅助设施。"}], "cross_boundary_rule": "若内容涉及“道口安全”，若侧重道口路面、栏杆机械结构，主挂载本节点；若侧重信号控制、自动报警系统，主挂载铁路通信、信号。"}, {"node_code": "N_f8dff14d5091d98b", "definition": "研究无缝线路（长钢轨线路）的构造形式、钢轨联接方式、温度应力管理、锁定轨温及与道床、扣件相互作用关系的工程技术体系。", "boundary": "本节点聚焦于“无缝线路”这一特定构造形式。边界在于区分“无缝线路”与“普通线路”（普通线路有接头，归入轨道或钢轨联接）、“无缝线路”与“线路理论”（温度应力计算归入理论）。若涉及无缝线路的钢轨焊接工艺，侧重焊接技术归入钢轨联接及扣件，侧重整体构造归本节点。", "includes": ["无缝线路的构造形式（如温度应力式、放散式）及锁定轨温确定", "无缝线路的钢轨焊接、联接及与扣件、道床的相互作用构造", "无缝线路的养护维修标准及胀轨跑道预防构造措施"], "excludes": ["普通线路的钢轨接头构造（归入钢轨联接及扣件）", "无缝线路温度应力、纵向力理论计算（归入线路理论）", "钢轨焊接工艺细节（归入钢轨联接及扣件，若侧重焊接技术）"], "sibling_distinctions": [{"other_code": "N_94632274f58f3bf0", "rule": "区分依据为构造形式：轨道是线路整体构造；无缝线路是轨道中钢轨连续无接头的特定构造形式，侧重温度应力管理。"}, {"other_code": "N_963050fc8a384d06", "rule": "区分依据为对象：钢轨联接及扣件关注单个接头或扣件结构；无缝线路关注长钢轨整体构造及温度应力管理。"}], "cross_boundary_rule": "若内容涉及“无缝线路设计”，若侧重构造形式、锁定轨温、整体布局，主挂载本节点；若侧重钢轨焊接工艺，主挂载钢轨联接及扣件；若侧重温度应力计算，主挂载线路理论。"}]}
